SCHEMA_SQL = ("\nCREATE FUNCTION m3_evidence_share_pending(t uuid,c uuid,pid uuid,prior_revision integer) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT m3_evidence_named_actor(t,c,'proposal.share',pid) AND EXISTS(\n  SELECT 1 FROM proposals p JOIN confirmations cp ON cp.tenant_id=p.tenant_id AND cp.category_id=p.category_id\n   AND cp.subject_id=p.id WHERE p.tenant_id=t AND p.category_id=c AND p.id=pid AND p.owner_id=scope_actor()\n   AND cp.operation='proposal.share' AND cp.subject_type='proposal' AND cp.actor_id=scope_actor()\n   AND cp.product_id IS NULL AND cp.consumed AND cp.xmin::text::bigint=txid_current()%4294967296\n   AND (prior_revision IS NULL OR cp.revision=prior_revision) AND p.revision IN (cp.revision,cp.revision+1)\n   AND cp.snapshot->'payload'->>'proposal_id'=p.id::text\n   AND (cp.snapshot->'payload'->>'expected_revision')::integer=cp.revision)\n$$;\n", 'REVOKE ALL ON FUNCTION m3_evidence_share_pending(uuid,uuid,uuid,integer) FROM PUBLIC,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION m3_evidence_share_pending(uuid,uuid,uuid,integer) TO pdos_next_app', "\nCREATE FUNCTION m3_evidence_named_receipt_policy(t uuid,c uuid,op text,sid uuid,actor uuid,requester uuid,proof_id uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT actor=scope_actor() AND requester=scope_requester() AND actor=requester\n  AND m3_evidence_named_actor(t,c,op,sid) AND EXISTS(\n  SELECT 1 FROM confirmations cp WHERE cp.tenant_id=t AND cp.category_id=c AND cp.id=proof_id\n   AND cp.actor_id=actor AND cp.operation=op AND cp.subject_id=sid AND cp.consumed\n   AND cp.subject_type=(CASE WHEN op='proposal.share' THEN 'proposal' WHEN op='evidence.claim.withdraw' THEN 'claim' END)\n   AND cp.xmin::text::bigint=txid_current()%4294967296)\n$$;\n", 'REVOKE ALL ON FUNCTION m3_evidence_named_receipt_policy(uuid,uuid,text,uuid,uuid,uuid,uuid) FROM PUBLIC,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION m3_evidence_named_receipt_policy(uuid,uuid,text,uuid,uuid,uuid,uuid) TO pdos_next_app', "\nCREATE FUNCTION m3_evidence_satellite_policy(t uuid,c uuid,rid uuid,mode text) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT category_access(t,c) AND EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=t AND r.category_id=c AND r.id=rid\n  AND r.actor_id=scope_actor() AND r.requester_id=scope_requester()\n  AND CASE mode WHEN 'named' THEN\n   r.xmin::text::bigint=txid_current()%4294967296\n   AND m3_evidence_named_receipt_policy(t,c,r.operation,r.subject_id,r.actor_id,r.requester_id,r.confirmation_id)\n  WHEN 'decision' THEN r.operation='proposal.g0.decide' AND r.subject_type='proposal'\n   AND m3_proposal_reader(t,c,r.subject_id)\n  ELSE false END)\n$$;\n", 'REVOKE ALL ON FUNCTION m3_evidence_satellite_policy(uuid,uuid,uuid,text) FROM PUBLIC,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION m3_evidence_satellite_policy(uuid,uuid,uuid,text) TO pdos_next_app', '\nCREATE FUNCTION m3_evidence_consumption_policy(t uuid,c uuid,kid uuid,did uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT category_access(t,c) AND m3_claim_reader(t,c,kid) AND (category_access(t,c,true)\n  OR EXISTS(SELECT 1 FROM proposal_decisions d WHERE d.tenant_id=t AND d.category_id=c AND d.id=did\n   AND d.decided_by=scope_actor() AND scope_actor()=scope_requester()))\n$$;\n', 'REVOKE ALL ON FUNCTION m3_evidence_consumption_policy(uuid,uuid,uuid,uuid) FROM PUBLIC,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION m3_evidence_consumption_policy(uuid,uuid,uuid,uuid) TO pdos_next_app', 'DROP POLICY "m3_owner_share_update" ON "proposals"', 'CREATE POLICY "m3_owner_share_update" ON "proposals" AS PERMISSIVE FOR UPDATE TO pdos_next_app USING (owner_id=scope_actor() AND (m3_evidence_share_pending(tenant_id,category_id,id,revision) OR m3_evidence_share_pending(tenant_id,category_id,id,revision-1))) WITH CHECK (owner_id=scope_actor() AND (m3_evidence_share_pending(tenant_id,category_id,id,revision) OR m3_evidence_share_pending(tenant_id,category_id,id,revision-1)))', 'DROP POLICY "m3_owner_share_audience" ON "object_audiences"', 'CREATE POLICY "m3_owner_share_audience" ON "object_audiences" AS PERMISSIVE FOR ALL TO pdos_next_app USING (object_type=\'proposals\' AND owner_id=scope_actor() AND m3_evidence_share_pending(tenant_id,category_id,subject_id,NULL)) WITH CHECK (object_type=\'proposals\' AND owner_id=scope_actor() AND m3_evidence_share_pending(tenant_id,category_id,subject_id,NULL))', 'DROP POLICY "m3_owner_share_revision" ON "proposal_revisions"', 'CREATE POLICY "m3_owner_share_revision" ON "proposal_revisions" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND run_id IS NULL AND m3_evidence_share_pending(tenant_id,category_id,proposal_id,revision-1))', 'DROP POLICY "m3_evidence_named_receipt" ON "action_receipts"', 'CREATE POLICY "m3_evidence_named_receipt" ON "action_receipts" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (m3_evidence_named_receipt_policy(tenant_id,category_id,operation,subject_id,actor_id,requester_id,confirmation_id))', 'DROP POLICY "m3_evidence_named_receipt" ON "audit_entries"', 'CREATE POLICY "m3_evidence_named_receipt" ON "audit_entries" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'named\'))', 'DROP POLICY "m3_audit" ON "audit_entries"', 'CREATE POLICY "m3_audit" ON "audit_entries" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'decision\'))', 'DROP POLICY "m3_evidence_named_receipt" ON "outbox_events"', 'CREATE POLICY "m3_evidence_named_receipt" ON "outbox_events" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'named\'))', 'DROP POLICY "m3_outbox" ON "outbox_events"', 'CREATE POLICY "m3_outbox" ON "outbox_events" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'decision\'))', 'DROP POLICY "m3_evidence_named_receipt" ON "request_keys"', 'CREATE POLICY "m3_evidence_named_receipt" ON "request_keys" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'named\'))', 'DROP POLICY "m3_request_key" ON "request_keys"', 'CREATE POLICY "m3_request_key" ON "request_keys" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (actor_id=scope_actor() AND m3_evidence_satellite_policy(tenant_id,category_id,receipt_id,\'decision\'))', 'DROP POLICY "m3_consumption_insert" ON "claim_consumptions"', 'CREATE POLICY "m3_consumption_insert" ON "claim_consumptions" AS PERMISSIVE FOR INSERT TO pdos_next_app WITH CHECK (m3_evidence_consumption_policy(tenant_id,category_id,claim_id,decision_id))')

